<script setup lang="ts">
import { ref } from "vue"; import { ElMessage } from "element-plus"; import { auditApi } from "../api/ops"; import type { AuditLog, PageResponse } from "../types";
const eventType=ref(""); const userId=ref(""); const data=ref<PageResponse<AuditLog>|null>(null); const loading=ref(false); async function load(){loading.value=true;try{data.value=await auditApi.logs({page:1,page_size:100,event_type:eventType.value,user_id:userId.value})}finally{loading.value=false}} void load();
async function exportLogs(){try{const blob=await auditApi.exportCsv({event_type:eventType.value,user_id:userId.value});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="audit-logs.csv";a.click();URL.revokeObjectURL(url)}catch(e){ElMessage.error(e instanceof Error?e.message:"导出失败")}}
</script><template><el-card class="page-card" header="审计日志"><template #header><div class="card-header"><span>审计日志</span><el-space><el-button @click="load">刷新</el-button><el-button @click="exportLogs">导出 CSV</el-button></el-space></div></template><el-space class="toolbar" wrap><el-input v-model="eventType" placeholder="事件类型" clearable/><el-input v-model="userId" placeholder="用户 ID" clearable/><el-button type="primary" @click="load">查询</el-button></el-space><el-table v-loading="loading" :data="data?.items||[]"><el-table-column prop="created_at" label="时间" width="190"/><el-table-column prop="event_type" label="事件" width="180"/><el-table-column prop="user_id" label="用户" width="180"/><el-table-column prop="request_id" label="请求 ID" min-width="220" show-overflow-tooltip/><el-table-column label="详情" min-width="300"><template #default="s">{{ JSON.stringify(s.row.payload) }}</template></el-table-column></el-table></el-card></template>
